#include "orbits/bifurcation.hpp"
#include "runtime/interpreter.hpp"
#include <chrono>
#include <cmath>
#include <filesystem>
#include <iostream>

namespace {
int checks=0,failures=0;void check(bool value,const char* text){++checks;if(!value){++failures;std::cerr<<"FAIL: "<<text<<'\n';}}
template<class F>void rejected(F action,const char* text){try{action();check(false,text);}catch(const std::exception&){check(true,text);}}
auto model(const std::string& source){auto a=penta::language::analyse(source);if(!a.ok()){for(const auto& d:a.diagnostics)std::cerr<<d.message<<'\n';throw std::runtime_error("Bifurcation fixture did not parse.");}return *a.program.statements.front().ode;}
#ifndef PENTA_BIFURCATION_NATIVE_ONLY
void language(const std::string& source,const penta::runtime::ExecutionOptions& options,bool expected=true){const auto result=penta::runtime::execute(source,{},options);check(result.ok()==expected,"Bifurcation language accepts/rejects the expected scope.");if(result.ok()!=expected){for(const auto& d:result.analysis.diagnostics)std::cerr<<d.code<<": "<<d.message<<'\n';for(const auto& d:result.runtimeDiagnostics)std::cerr<<d.code<<": "<<d.message<<'\n';}}
#endif
}
int main(int argc,char** argv){try{
    using namespace penta::orbits::bifurcation;const auto path=std::filesystem::temp_directory_path()/("penta-bifurcation-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));penta::ode::NativeOptions native;native.cacheDirectory=path/"kernels";std::size_t compilations=0;native.compilationFinished=[&](double){++compilations;};const auto modules=argc>1?std::filesystem::absolute(argv[1]):std::filesystem::path{};
    Options options;options.parameter=0;options.tolerance=1e-9;const auto foldModel=model("ode saddle_node(t,real x;real mu){x'=mu+x*x;}");const auto fold=refine(foldModel,1,{.3},{-.1},options,native,modules);
    check(fold.report.converged&&std::string(fold.report.status)=="fold_candidate","Saddle-node augmented equations refine a true fold candidate.");check(std::abs(fold.state[0])<1e-8&&std::abs(fold.report.final_parameter)<1e-8,"Fold point agrees with the analytic normal form.");check(fold.report.simple&&fold.report.transverse&&fold.report.nondegenerate&&fold.report.criticality_computed,"Fold exposes simple eigenvalue and both nondegeneracy coefficients.");check(std::abs(std::abs(fold.report.crossing)-1)<1e-8&&std::abs(std::abs(fold.report.quadratic)-1)<1e-8,"Generated AD2 fold coefficients match exact derivatives.");
    const auto before=compilations;auto changed=options;changed.tolerance=1e-8;const auto reused=refine(foldModel,1,{.2},{-.05},changed,native,modules);check(compilations==before&&reused.key==fold.key&&reused.derivativeKey==fold.derivativeKey,"Runtime seed/parameter/tolerance edits reuse both native model and AD kernels.");
    const auto pentModel=model("ode pentfold(t,pentarnion q;pentarnion A){q'=scalar(A)+scalar(q)*scalar(q)-pure(q);}");const auto pentFold=refine(pentModel,1,{.2,.1,-.1,.15,.05},{-.05,10,20,30,40},options,native,modules);check(pentFold.report.converged&&std::string(pentFold.report.status)=="fold_candidate"&&pentFold.state.size()==5,"Full Pentarnion state and selected parameter coefficient refine without dropping dimensions.");for(const double value:pentFold.state)check(std::abs(value)<1e-7,"Pentarnion fold solves every retained coefficient equation.");
    const auto pitchfork=model("ode degenerate(t,real x;real mu){x'=mu*x-x*x*x;}");const auto degenerate=refine(pitchfork,1,{0},{0},options,native,modules);check(degenerate.report.converged&&!degenerate.report.nondegenerate&&!degenerate.report.transverse&&std::string(degenerate.report.status)=="inconclusive","A degenerate zero eigenvalue is not mislabeled as a generic fold.");
    const auto hopfModel=model("ode radial(t,real x,real y;real mu){x'=mu*x-y-(x*x+y*y)*x;y'=x+mu*y-(x*x+y*y)*y;}");auto hopfOptions=options;hopfOptions.kind=PENTA_BIFURCATION_HOPF;hopfOptions.auxiliary=0;const auto hopf=refine(hopfModel,1,{.1,.05},{.1},hopfOptions,native,modules);
    check(hopf.report.converged&&std::string(hopf.report.status)=="hopf_candidate","Native AD2 augmented system refines a simple Hopf crossing.");check(std::hypot(hopf.state[0],hopf.state[1])<1e-7&&std::abs(hopf.report.final_parameter)<1e-7&&std::abs(hopf.report.final_auxiliary-1)<1e-7,"Hopf location/frequency agree with the analytic normal form.");check(hopf.report.simple&&hopf.report.transverse&&std::abs(hopf.report.crossing-1)<1e-7,"Hopf crossing includes equilibrium-branch motion.");check(!hopf.report.criticality_computed&&!hopf.report.nondegenerate,"No third-derivative Hopf criticality is invented.");
    const auto shifted=model("ode shifted(t,real x,real y;real mu){x'=(mu+.5*x)*(x-mu)-y-((x-mu)*(x-mu)+y*y)*(x-mu);y'=x-mu+(mu+.5*x)*y-((x-mu)*(x-mu)+y*y)*y;}");const auto movingEquilibrium=refine(shifted,1,{.1,0},{.1},hopfOptions,native,modules);check(movingEquilibrium.report.converged&&std::abs(movingEquilibrium.report.crossing-1.5)<1e-6,"Hopf transversality includes J_x times the nonconstant equilibrium branch derivative.");
    const auto zeroHopf=model("ode multiple(t,real x,real y,real z;real mu){x'=mu+x*x;y'=-z;z'=y;}");const auto extraCenter=refine(zeroHopf,1,{0,0,0},{0},options,native,modules);check(extraCenter.report.converged&&extraCenter.report.other_critical_modes==2&&std::string(extraCenter.report.status)=="inconclusive","Extra center modes prevent a codimension-one fold classification.");
    const auto center=model("ode center(t,real x,real y;real mu){x'=-y;y'=x;}");const auto noCrossing=refine(center,1,{0,0},{.1},hopfOptions,native,modules);check(noCrossing.report.converged&&!noCrossing.report.transverse&&std::string(noCrossing.report.status)=="inconclusive","A persistent center without eigenvalue crossing is not a Hopf candidate.");
    const auto flipModel=model("ode flip(t,real x,real y,real u,real v;real mu){x'=-y+(1-x*x-y*y)*x;y'=x+(1-x*x-y*y)*y;u'=((mu-1)/2+(mu+1)*x/2)*u+((mu+1)*y/2-.5)*v;v'=((mu+1)*y/2+.5)*u+((mu-1)/2-(mu+1)*x/2)*v;}");auto flipOptions=options;flipOptions.kind=PENTA_BIFURCATION_FLIP;flipOptions.auxiliary=6.2;flipOptions.tolerance=1e-7;flipOptions.solver.method=penta::ode::Method::Bdf;flipOptions.solver.rtol=1e-10;flipOptions.solver.atol=1e-12;flipOptions.fdAgreement=.01;const auto flip=refine(flipModel,1,{1,0,0,0},{.01},flipOptions,native,modules);
    std::cout<<"Flip refinement: "<<flip.report.status<<", mu="<<flip.report.final_parameter<<", T="<<flip.report.final_auxiliary<<", residual="<<flip.report.residual<<", crossing="<<flip.report.crossing<<", FD agreement="<<flip.report.step_difference<<'\n';
    check(flip.report.converged&&std::string(flip.report.status)=="period_doubling_candidate","A known autonomous4D normal form refines a simple period-doubling candidate.");check(std::abs(flip.report.final_parameter)<1e-6&&std::abs(flip.report.final_auxiliary-2*std::acos(-1.0))<1e-6,"Flip parameter and cycle period match the exact model.");check(std::abs(flip.report.critical_real+1)<1e-6&&flip.report.neutral_error<1e-6&&flip.report.amplitude>1,"Flip retains closure, neutral multiplier and nontrivial orbit evidence.");check(flip.report.simple&&flip.report.transverse&&flip.report.step_refined&&std::abs(flip.report.crossing+2*std::acos(-1.0))<.005,"Floquet crossing has an independent exact derivative and step refinement.");check(!flip.report.criticality_computed,"Cubic period-doubling criticality/emerging branch direction is not inferred.");
    auto low=options;low.maximumBytes=1024;rejected([&]{(void)refine(foldModel,1,{.1},{0},low,native,modules);},"Augmented/native derivative buffers respect max_bytes.");
    const auto forced=model("ode forced(t,real x;real mu){x'=mu+x*x+sin(t);}");rejected([&]{(void)refine(forced,1,{.1},{0},options,native,modules);},"Nonautonomous bifurcation conventions are not silently inferred.");
    auto cancelled=native;cancelled.cancellation=std::make_shared<std::atomic_bool>(true);rejected([&]{(void)refine(foldModel,1,{.1},{0},options,cancelled,modules);},"Bifurcation refinement supports cooperative cancellation.");
#ifndef PENTA_BIFURCATION_NATIVE_ONLY
    penta::runtime::ExecutionOptions execution;execution.dataDirectory=path;execution.odeCacheDirectory=native.cacheDirectory;execution.numericModuleDirectory=modules;
    language("ode fold(t,real x;real mu){x'=mu+x*x;}record r=refinebifurcation(fold,[.2],options(kind=\"fold\",parameter=\"mu\",parameters=options(mu=-.05)));assert(r.converged==1&&r.simple==1&&r.transverse==1);assert(abs(r.parameter)<1e-6);",execution);
    language("ode h(t,real x,real y;real mu){x'=mu*x-y;y'=x+mu*y;}record r=refinebifurcation(h,[0,0],options(kind=\"hopf\",parameter=\"mu\",parameters=options(mu=.1)));assert(abs(r.frequency-1)<1e-6);assert(r.criticality_computed==0);",execution);
#endif
}catch(const std::exception& error){++failures;std::cerr<<error.what()<<'\n';}std::cout<<checks<<" native bifurcation checks, "<<failures<<" failures\n";return failures?1:0;}
